public static boolean exist(AIBId _id)
{
    return (select firstonly RecId from AIBBookTable where AIBBookTable.Id == _id).RecId != 0;
}

public static AIBBookTable findRecId(RecId _recid)
{
    AIBBookTable bookTable;

    select firstonly bookTable
        where bookTable.RecId == _recid;

    return bookTable;
}

public static AIBBookTable find(AIBId _id)
{
    AIBBookTable bookTable;

    select firstonly bookTable
        where bookTable.Id == _id;

    return bookTable;
}

public static int selectCountByGenre(AIBGenreEnum _genre)
{
    AIBBookTable bookTable;

    select count(RecId) from bookTable
        group by Genre
        where bookTable.Genre == _genre;

    return bookTable.RecId;
}

[SysClientCacheDataMethod(true)]
public display AIBAuthorFullName dispAuthorFullName()
{
    AIBAuthorTable authorTable = AIBAuthorTable::findRecId(this.Author);
    return authorTable.FirstName + ' ' + authorTable.LastName;
}

[SysClientCacheDataMethod(true)]
public display AIBInventoryQty displayCurrentInventory()
{
    return this.currentInventory();
}

public Qty currentInventory(RecId _excludeTransactionRecId = 0)
{
    AIBBookInventoryTransaction transactions;

    select sum(RecId) from transactions
        where transactions.Book == this.RecId
        && transactions.RecId != _excludeTransactionRecId;

    return transactions.Qty;

}

public Common AuthorTableLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(AIBAuthorTable), _formReferenceControl);

    refTableLookup.parmQuery(this.getLookupQuery());
    refTableLookup.addSelectionField(fieldNum(AIBAuthorTable, Id));
    refTableLookup.addSelectionField(fieldNum(AIBAuthorTable, FirstName));
    refTableLookup.addSelectionField(fieldNum(AIBAuthorTable, LastName));
    refTableLookup.addSelectionField(fieldNum(AIBAuthorTable, IsDead));

    return refTableLookup.performFormLookup();
}

private Query getLookupQuery()
{
    Query q = new Query();
    QueryBuildDataSource qbds = q.addDataSource(tableNum(AIBAuthorTable));
    qbds.addRange(fieldNum(AIBAuthorTable, IsDead)).value(queryVALUE(NoYes::No));
    return q;
}

public void initValue()
{
    super();

    this.Author = CustParameters::find().AIBAuthorTable;
}
